/* GENERADO por docs/manuales/tools/generar.js desde docs/manuales/*.md: no editar a mano. */
window.MANUALES_DATA = {"gerencia":{"n":"Gerencia","html":"<h2>Qué hace Gerencia</h2>\n<p>Gerencia ve todo el negocio, aprueba lo que los demás puestos piden (precios, diferencias, pagos del portal, solicitudes), configura las reglas del sistema y revisa la auditoría. Es el único puesto que cambia las reglas de pago de nómina, los bonos y el PIN de gerencia.</p>\n<p>Gerencia también puede entrar a las pantallas de los otros puestos. Para cada puesto hay un manual aparte.</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Gerencia</b>.</li>\n<li>Mira el <b>Resumen</b> y la tarjeta <b>Requiere atención</b>.</li>\n<li>En <b>Por aprobar</b>, responde <b>Precios por aprobar</b>, <b>Solicitudes</b>, <b>Diferencias</b> y <b>Pagos del portal</b>.</li>\n<li>Mira <b>Producción</b>, <b>Ventas</b> y <b>Administración</b> en el Resumen.</li>\n<li>De vez en cuando, revisa la <b>Auditoría</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Gerencia</b>.</li>\n<li>Se abre el <b>Resumen</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-01.png\" alt=\"Resumen de Gerencia\" loading=\"lazy\"><figcaption>Resumen de Gerencia</figcaption></figure>\n<hr>\n<h2>Cómo apruebo los precios</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Por aprobar</b> y abre la pestaña <b>Precios</b>.</li>\n<li>Revisa cada cambio.</li>\n<li>Pulsa <b>Aprobar</b> o <b>Rechazar</b>.</li>\n<li>Si quieres, escribe un motivo.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-02.png\" alt=\"Precios por aprobar\" loading=\"lazy\"><figcaption>Precios por aprobar</figcaption></figure>\n<div class=\"mn-nota\">Un precio nuevo solo vale cuando Gerencia lo aprueba.</div>\n<hr>\n<h2>Cómo respondo las solicitudes de los puestos</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Por aprobar</b> y abre la pestaña <b>Solicitudes</b>.</li>\n<li>En cada solicitud pulsa <b>Aprobar</b> (puedes dejar un comentario) o <b>Rechazar</b> (el motivo es obligatorio).</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-03.png\" alt=\"Solicitudes\" loading=\"lazy\"><figcaption>Solicitudes</figcaption></figure>\n<hr>\n<h2>Cómo resuelvo las diferencias y los pagos del portal</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Por aprobar</b> y abre la pestaña <b>Diferencias</b>.</li>\n<li>Revisa cada diferencia y pulsa <b>Aprobar</b> o <b>Rechazar</b> (para rechazar, escribe el motivo).</li>\n<li>Abre la pestaña <b>Pagos del portal</b>.</li>\n<li>En cada pago pulsa <b>Confirmar y aplicar</b> o <b>Rechazar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-04.png\" alt=\"Diferencias\" loading=\"lazy\"><figcaption>Diferencias</figcaption></figure>\n<div class=\"mn-nota\">Si la fecha del pago es anterior, el sistema pide el PIN de gerencia.</div>\n<hr>\n<h2>Cómo configuro el sistema desde cero</h2>\n<h3>Los bancos</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ajustes</b> y abre la pestaña <b>Bancos</b>.</li>\n<li>Pulsa <b>Agregar banco</b>.</li>\n<li>Escribe el nombre del banco, la moneda, el número de cuenta y el titular.</li>\n<li>Escribe también el teléfono (Pago Móvil), la cédula y el RIF.</li>\n<li>Pulsa <b>Guardar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-05.png\" alt=\"Bancos de la empresa\" loading=\"lazy\"><figcaption>Bancos de la empresa</figcaption></figure>\n<div class=\"mn-nota\">La tasa del dólar no se escribe: se lee sola del BCV.</div>\n<h3>Los horarios, las reglas de pago y el bono</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ajustes</b> y abre la pestaña <b>Turnos y bonos</b>.</li>\n<li>En <b>Horario por turno</b>, pon cuándo entran y salen el Diurno y el Nocturno.</li>\n<li>En <b>Reglas de pago de nómina</b>, pon la jornada completa, el recargo de hora extra (%) y las deducciones de ley (%).</li>\n<li>En <b>Bono de producción</b>, elige <b>Por kilo</b> o <b>Monto fijo</b> y la meta de kilos por turno.</li>\n<li>Pulsa <b>Guardar parámetros</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-06.png\" alt=\"Turnos y bonos\" loading=\"lazy\"><figcaption>Turnos y bonos</figcaption></figure>\n<h3>El PIN de gerencia</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ventas</b>, <b>Clientes y catálogo</b> y abre la pestaña <b>Ajustes</b>.</li>\n<li>En <b>PIN de gerencia</b>, escribe el PIN (de 4 a 12 números) y pulsa <b>Crear PIN</b> (si ya hay uno, el botón dice <b>Cambiar PIN</b>).</li>\n<li>Si quieres, llena el <b>Membrete de los documentos</b> y pulsa <b>Guardar ajustes</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-07.png\" alt=\"PIN de gerencia\" loading=\"lazy\"><figcaption>PIN de gerencia</figcaption></figure>\n<div class=\"mn-nota\">El PIN se pide para anotar un pago con fecha pasada y para perdonar mora.</div>\n<h3>Las reglas de caja y nómina</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ajustes</b> y abre la pestaña <b>Reglas de caja y nómina</b>.</li>\n<li>Revisa el <b>Fondo fijo ($)</b>, el <b>Umbral de compra de contado ($)</b>, <b>Reponer cuando quede menos de (%)</b> y la <b>Tolerancia de peso en recepción (%)</b>.</li>\n<li>Revisa los préstamos: días de entrega, tope por empleado ($) y cuotas máximas.</li>\n<li>Pulsa <b>Guardar políticas</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-08.png\" alt=\"Reglas de caja y nómina\" loading=\"lazy\"><figcaption>Reglas de caja y nómina</figcaption></figure>\n<hr>\n<h2>Cómo cargo la información base</h2>\n<ol start=\"1\">\n<li><b>Productos</b>: en <b>Ventas</b>, <b>Clientes y catálogo</b>, abre <b>Productos e inventario</b> y pulsa <b>Producto nuevo</b>. Escribe SKU, nombre, gramaje, categoría (<b>Papas</b> o <b>Salsas</b>) e IVA (%) y pulsa <b>Guardar</b>.</li>\n<li><b>Clientes</b>: en <b>Ventas</b>, <b>Clientes y catálogo</b>, pestaña <b>Clientes</b>, pulsa <b>Cliente nuevo</b>.</li>\n<li><b>Personas</b>: entra como Recursos humanos, abre <b>Personas</b> y pulsa <b>Agregar persona</b>.</li>\n<li><b>Proveedores</b>: en <b>Administración</b>, <b>Compras</b>, abre <b>Proveedores</b> y pulsa <b>Nuevo proveedor</b>.</li>\n<li><b>Vehículos</b>: en <b>Administración</b>, abre <b>Flota</b> y pulsa <b>Agregar vehículo</b>.</li>\n<li><b>Conteo inicial de producto terminado</b>: pulsa <b>Cargar el conteo inicial</b>, llena el conteo y pulsa <b>Guardar el conteo</b>. Solo se hace una vez.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-09.png\" alt=\"Producto nuevo\" loading=\"lazy\"><figcaption>Producto nuevo</figcaption></figure>\n<hr>\n<h2>Cómo defino los mínimos de inventario</h2>\n<ol start=\"1\">\n<li>En el <b>Resumen</b>, mira la tarjeta <b>Inventario de producción</b>.</li>\n<li>Pulsa <b>Definir mínimo</b> (o <b>Cambiar mínimo</b>) en cada insumo.</li>\n<li>Escribe cuánto es lo mínimo.</li>\n<li>Pulsa <b>Cargar</b> para los <b>Kilos de papa por bolsón</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-10.png\" alt=\"Inventario de producción con barras\" loading=\"lazy\"><figcaption>Inventario de producción con barras</figcaption></figure>\n<hr>\n<h2>Cómo reviso la auditoría y los reportes</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Auditoría</b>.</li>\n<li>Consulta lo que se hizo en el sistema. Solo se mira: no se puede cambiar.</li>\n<li>Si quieres guardarla, pulsa <b>Descargar CSV</b>.</li>\n<li>Pulsa <b>Opciones</b> y elige <b>Reportes</b> para ver los <b>Cambios en existencias</b> y las <b>Solicitudes de compra</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-11.png\" alt=\"Auditoría\" loading=\"lazy\"><figcaption>Auditoría</figcaption></figure>\n<hr>\n<h2>Cómo decido quién ve qué</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ajustes</b> y abre la pestaña <b>Quién ve qué</b>.</li>\n<li>Revisa qué puede abrir cada puesto.</li>\n<li>En la pestaña <b>Funciones extra</b> puedes darle a un puesto una función más.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-12.png\" alt=\"Quién ve qué\" loading=\"lazy\"><figcaption>Quién ve qué</figcaption></figure>\n<hr>\n<h2>Los manuales de los demás puestos</h2>\n<p>Para ver cómo trabaja cada puesto, abre <b>Ayuda</b> y entra en la pestaña de manuales. Ahí están los seis manuales: Gerencia, Administración, Producción, Logística, Ventas y Recursos humanos.</p>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>Anulé un cobro mal puesto</h3>\n<ol start=\"1\">\n<li>Entra en <b>Administración</b>, <b>Cobranza</b>, pestaña <b>Cobros hechos</b>, y pulsa <b>Anular</b> en la fila.</li>\n<li>Escribe el <b>Motivo de la anulación</b>.</li>\n<li>El cobro no se borra: queda marcado como anulado.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-13.png\" alt=\"Anular un cobro\" loading=\"lazy\"><figcaption>Anular un cobro</figcaption></figure>\n<h3>Corregir la merma de un turno ya cerrado</h3>\n<ol start=\"1\">\n<li>Solo Gerencia puede hacerlo, con una nota.</li>\n<li>Revisa el Resumen de Producción: la diferencia aparece como «Sin explicar».</li>\n</ol>\n<h3>Un puesto pide algo que no puede cambiar</h3>\n<ol start=\"1\">\n<li>Aparece en <b>Solicitudes</b> (en <b>Por aprobar</b>).</li>\n<li>Pulsa <b>Aprobar</b> o <b>Rechazar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/gerencia-14.png\" alt=\"Solicitudes de los puestos\" loading=\"lazy\"><figcaption>Solicitudes de los puestos</figcaption></figure>\n<h3>Falta el motivo de merma «Agua evaporada»</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Ajustes</b> y abre la pestaña <b>Zonas y mermas</b> (o <b>Motivos de merma</b>).</li>\n<li>Agrega el motivo.</li>\n</ol>","pasos":61,"fotos":14},"administracion":{"n":"Administración","html":"<h2>Qué hace Administración</h2>\n<p>Administración cuida el dinero de la empresa: hace las compras a los proveedores, paga lo que se debe, cobra a los clientes, lleva la caja chica y entrega los préstamos. También mantiene al día los precios (con la aprobación de Gerencia), los proveedores y los vehículos.</p>\n<p>Administración <b>no recibe</b> la mercancía (eso lo hace Producción) y <b>no cambia</b> las reglas de pago ni los bonos (eso lo hace Gerencia). Lo que no puede cambiar, lo pide con «Pedir autorización».</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Administración</b>.</li>\n<li>Empieza por el <b>Resumen</b>: mira lo pendiente.</li>\n<li>Haz las compras que hagan falta con <b>Nueva compra</b>.</li>\n<li>Cobra lo que deben los clientes con <b>Cobranza</b> y paga a los proveedores en <b>Por pagar</b>.</li>\n<li>Anota los gastos de caja chica y, al cierre, cuenta la caja con <b>Arqueo</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Administración</b>.</li>\n<li>Se abre el <b>Resumen</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-01.png\" alt=\"Resumen de Administración\" loading=\"lazy\"><figcaption>Resumen de Administración</figcaption></figure>\n<div class=\"mn-nota\">Arriba del Resumen están los botones <b>Cobranza</b> y <b>Nueva compra</b>.</div>\n<hr>\n<h2>Cómo hago una compra</h2>\n<ol start=\"1\">\n<li>En el Resumen, pulsa <b>Nueva compra</b> (o pulsa <b>Opciones</b>, elige <b>Compras</b> y abre <b>Hacer compra</b>).</li>\n<li>En <b>Proveedor</b>, toca al proveedor (o pulsa <b>Nuevo proveedor</b>).</li>\n<li>En <b>Productos</b>, pon la cantidad de cada producto con <b>+</b> y <b>−</b>.</li>\n<li>Escribe el número de la factura del proveedor.</li>\n<li>Escribe la fecha de la factura.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-02.png\" alt=\"Compra con proveedor y productos\" loading=\"lazy\"><figcaption>Compra con proveedor y productos</figcaption></figure>\n<ol start=\"6\">\n<li>En <b>¿Cómo se paga?</b> elige el banco o la cuenta y el plazo en días.</li>\n<li>Pulsa <b>HACER LA COMPRA</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-03.png\" alt=\"Cómo se paga y botón HACER LA COMPRA\" loading=\"lazy\"><figcaption>Cómo se paga y botón HACER LA COMPRA</figcaption></figure>\n<div class=\"mn-nota\">La compra se hace en un solo paso: no hay que validarla después.<br>Producción la ve en <b>Pedidas por recibir</b> y, cuando la recibe, queda lista.<br>También se compran los <b>Bolsones</b> y las <b>Bolsas de presentación</b>.</div>\n<hr>\n<h2>Cómo veo las diferencias de compras</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Compras</b>.</li>\n<li>Abre la pestaña <b>Diferencias</b>.</li>\n<li>Lee cada compra que llegó distinta a lo pedido y el motivo que escribió Producción.</li>\n<li>Úsalo para reclamar al proveedor.</li>\n<li>Marca cada una como vista.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-04.png\" alt=\"Diferencias de compras\" loading=\"lazy\"><figcaption>Diferencias de compras</figcaption></figure>\n<div class=\"mn-nota\">Solo se paga lo que llegó.</div>\n<hr>\n<h2>Cómo anoto otras compras</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Compras</b>.</li>\n<li>Abre la pestaña <b>Otras compras</b>.</li>\n<li>Escribe qué se compró.</li>\n<li>Elige el proveedor.</li>\n<li>Escribe el monto y elige la partida contable.</li>\n<li>Escribe el <b>Motivo de la compra</b> (es obligatorio).</li>\n<li>Pulsa <b>Registrar compra</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-05.png\" alt=\"Otras compras\" loading=\"lazy\"><figcaption>Otras compras</figcaption></figure>\n<hr>\n<h2>Cómo pago a un proveedor</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Pagos y caja</b>.</li>\n<li>Abre la pestaña <b>Por pagar</b>.</li>\n<li>Busca la compra del proveedor.</li>\n<li>Pulsa <b>Registrar pago</b> (o <b>Registrar abono</b> si pagas una parte).</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-06.png\" alt=\"Por pagar\" loading=\"lazy\"><figcaption>Por pagar</figcaption></figure>\n<hr>\n<h2>Cómo cobro a un cliente</h2>\n<ol start=\"1\">\n<li>En el Resumen, pulsa <b>Cobranza</b> (o pulsa <b>Opciones</b>, elige <b>Cobranza</b> y abre <b>Registrar cobro</b>).</li>\n<li>Paso 1: elige al cliente.</li>\n<li>Paso 2: marca las notas y facturas que paga (o pulsa <b>Repartir el pago (más antigua primero)</b>).</li>\n<li>Paso 3: escribe la fecha, el monto recibido (Bs), el banco y el número de referencia.</li>\n<li>Pulsa <b>Registrar pago</b>.</li>\n<li>Pulsa <b>Confirmar</b>.</li>\n<li>Si quieres el comprobante, pulsa <b>Ver e imprimir el recibo</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-07.png\" alt=\"Registrar cobro\" loading=\"lazy\"><figcaption>Registrar cobro</figcaption></figure>\n<h3>Para ver a quién cobrar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Cobranza</b>.</li>\n<li>Abre la pestaña <b>Quién debe</b>.</li>\n<li>Pulsa <b>WhatsApp</b>, <b>Llamar</b> o <b>Registrar cobro</b> en la fila del cliente.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-08.png\" alt=\"Quién debe\" loading=\"lazy\"><figcaption>Quién debe</figcaption></figure>\n<h3>Para revisar los pagos del portal del cliente</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Cobranza</b>.</li>\n<li>Abre la pestaña <b>Pagos del portal</b>.</li>\n<li>En cada pago pulsa <b>Confirmar y aplicar</b> o <b>Rechazar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-15.png\" alt=\"Pagos del portal\" loading=\"lazy\"><figcaption>Pagos del portal</figcaption></figure>\n<div class=\"mn-nota\">Si la fecha del pago es anterior, el sistema pide el PIN de gerencia.</div>\n<hr>\n<h2>Cómo anoto un gasto de caja chica</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Pagos y caja</b>.</li>\n<li>Abre la pestaña <b>Caja chica</b>.</li>\n<li>Baja hasta <b>Registrar gasto</b>.</li>\n<li>Llena número, fecha, proveedor, RIF, monto, categoría y justificación.</li>\n<li>Sube la foto del comprobante.</li>\n<li>Pulsa <b>Guardar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-09.png\" alt=\"Registrar gasto de caja chica\" loading=\"lazy\"><figcaption>Registrar gasto de caja chica</figcaption></figure>\n<h3>Para contar la caja</h3>\n<ol start=\"1\">\n<li>En <b>Caja chica</b>, mira la tarjeta <b>Arqueo</b>.</li>\n<li>Escribe el <b>Efectivo contado ahora ($)</b>.</li>\n<li>Pulsa <b>Guardar arqueo</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entrego un préstamo</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Pagos y caja</b>.</li>\n<li>Abre la pestaña <b>Préstamos</b>.</li>\n<li>Elige al empleado.</li>\n<li>Escribe monto, cuotas, fecha de entrega y motivo.</li>\n<li>Pulsa <b>Entregar préstamo y generar recibo</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-10.png\" alt=\"Préstamos\" loading=\"lazy\"><figcaption>Préstamos</figcaption></figure>\n<div class=\"mn-nota\">La cuota se puede descontar después al pagar la nómina (lo hace Recursos humanos).</div>\n<hr>\n<h2>Cómo pongo un precio</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Precios</b>.</li>\n<li>Abre la pestaña <b>Por lista</b>.</li>\n<li>Elige <b>Minorista</b>, <b>Mayorista</b> o <b>Gran Mayor</b>.</li>\n<li>Toca el precio que quieres cambiar.</li>\n<li>Si no hay precio, pulsa <b>Cargar precios</b> y escribe el de contado y el de crédito.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-11.png\" alt=\"Precios por categoría\" loading=\"lazy\"><figcaption>Precios por categoría</figcaption></figure>\n<div class=\"mn-nota\">Tu cambio se envía a Gerencia para que lo apruebe. Puedes ver cómo va en <b>Historial de cambios</b>.</div>\n<hr>\n<h2>Cómo veo y defino el inventario mínimo</h2>\n<ol start=\"1\">\n<li>En el Resumen, mira la tarjeta <b>Inventario de producción</b>.</li>\n<li>Cada insumo tiene una barra: verde si alcanza, amarillo si se acerca al mínimo, rojo si está en el mínimo o por debajo.</li>\n<li>Pulsa <b>Definir mínimo</b> (o <b>Cambiar mínimo</b>) y escribe cuánto es lo mínimo.</li>\n<li>Debajo de las barras, pulsa <b>Cargar</b> para anotar los <b>Kilos de papa por bolsón</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-12.png\" alt=\"Inventario de producción con barras\" loading=\"lazy\"><figcaption>Inventario de producción con barras</figcaption></figure>\n<hr>\n<h2>Cómo registro a proveedores y vehículos</h2>\n<h3>Un proveedor</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Compras</b>.</li>\n<li>Abre la pestaña <b>Proveedores</b>.</li>\n<li>Pulsa <b>Nuevo proveedor</b>.</li>\n<li>Escribe nombre, RIF, qué vende y condición de pago.</li>\n<li>Pulsa <b>Guardar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-13.png\" alt=\"Proveedores\" loading=\"lazy\"><figcaption>Proveedores</figcaption></figure>\n<h3>Un vehículo</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Flota</b>.</li>\n<li>Pulsa <b>Agregar vehículo</b>.</li>\n<li>Escribe placa, tipo, marca, modelo, capacidades, estado, chofer habitual y cuándo vencen el seguro y los documentos.</li>\n<li>Pulsa <b>Guardar</b>.</li>\n</ol>\n<hr>\n<h2>Cómo veo los reportes, los bonos y las reglas</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Registro de ventas</b> para ver los <b>Reportes de ventas</b>.</li>\n<li>Pulsa <b>Opciones</b> y elige <b>Bonos</b> para ver <b>Turno en vivo</b> y las metas.</li>\n<li>Para las reglas de caja, entra en <b>Pagos y caja</b> y pulsa <b>Políticas</b> (arriba a la derecha).</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-14.png\" alt=\"Reportes de ventas\" loading=\"lazy\"><figcaption>Reportes de ventas</figcaption></figure>\n<div class=\"mn-nota\">Los parámetros de turnos y bonos solo los cambia Gerencia. Si hace falta un cambio, pulsa <b>Pedir autorización</b>.</div>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>«Referencia repetida: no se guardó» al cobrar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Ver el pago existente</b>.</li>\n<li>Revisa si ese pago ya estaba anotado.</li>\n<li>Solo si no estaba, cámbiala y vuelve a intentar.</li>\n</ol>\n<div class=\"mn-nota\">Un pago con fecha pasada pide el <b>PIN de gerencia</b>. Pídelo a Gerencia.</div>\n<h3>No puedo cambiar algo (por ejemplo un parámetro o una regla)</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Autorización</b>, arriba.</li>\n<li>Pulsa <b>Pedir autorización</b>.</li>\n<li>En <b>¿Qué quieres cambiar?</b> elige lo que necesitas.</li>\n<li>Escribe el <b>Motivo (obligatorio)</b>.</li>\n<li>Pulsa <b>Enviar solicitud</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/administracion-16.png\" alt=\"Ventana para pedir autorización\" loading=\"lazy\"><figcaption>Ventana para pedir autorización</figcaption></figure>\n<h3>Quiero saber qué respondieron</h3>\n<ol start=\"1\">\n<li>Abre <b>Mis solicitudes</b>.</li>\n<li>Mira la respuesta de Gerencia.</li>\n</ol>","pasos":89,"fotos":16},"produccion":{"n":"Producción","html":"<h2>Qué hace Producción</h2>\n<p>Producción recibe lo que llega (papa, insumos, bolsones), revisa que haya todo lo necesario, inicia el turno, hace las etapas de la producción en orden, anota la merma de cada etapa y cierra el turno. Lo empacado lo anota Logística.</p>\n<p>Producción <b>no ve precios ni costos</b>. Las compras las hace Administración.</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Producción</b>.</li>\n<li>En <b>Recibir</b>, recibe lo que llegó (<b>Pedidas por recibir</b>).</li>\n<li>En <b>Producir</b>, mira que los requisitos estén en verde y pulsa <b>Iniciar producción</b>.</li>\n<li>Haz las etapas una a una y pulsa <b>Terminar etapa</b>.</li>\n<li>Al final anota la merma y pulsa <b>Anotar merma y cerrar turno</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Producción</b>.</li>\n<li>Se abre la pantalla <b>Producir</b>. Arriba tienes tres botones grandes: <b>Recibir</b>, <b>Producir</b> e <b>Inventario disponible</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-01.png\" alt=\"Pantalla Producir con los requisitos\" loading=\"lazy\"><figcaption>Pantalla Producir con los requisitos</figcaption></figure>\n<hr>\n<h2>Cómo recibo lo que llegó</h2>\n<ol start=\"1\">\n<li>Pulsa el botón grande <b>Recibir</b>.</li>\n<li>Arriba, en <b>Pedidas por recibir</b>, busca la compra que llegó.</li>\n<li>Pulsa <b>Recibir</b> en esa compra.</li>\n<li>Escribe lo que llegó de cada producto.</li>\n<li>Si llegó distinto a lo pedido, el sistema te avisa: confirma y escribe el motivo.</li>\n<li>Pulsa el botón para guardar la recepción.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-02.png\" alt=\"Pedidas por recibir\" loading=\"lazy\"><figcaption>Pedidas por recibir</figcaption></figure>\n<div class=\"mn-nota\">La papa llega por sacos: cuenta los sacos y pesa los de muestra que pide la pantalla.<br>Los <b>Bolsones</b> y las <b>Bolsas de presentación</b> se reciben igual que cualquier compra.<br>Más abajo ves solo lo recibido hoy.<br>Elige <b>Quién recibe</b>. Si no hay nadie, agrégalo en «Cómo agrego a quien recibe».</div>\n<hr>\n<h2>Cómo inicio el turno</h2>\n<ol start=\"1\">\n<li>Pulsa el botón grande <b>Producir</b> (pestaña <b>Producir</b>).</li>\n<li>Mira los requisitos: papa, aceite, agua, sal, químicos, almidón, <b>Bolsones</b> y el personal del turno.</li>\n<li>Cada uno sale en verde con «Hay …» si alcanza.</li>\n<li>Si todos están en verde, pulsa <b>Iniciar producción</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-03.png\" alt=\"Requisitos en verde e Iniciar producción\" loading=\"lazy\"><figcaption>Requisitos en verde e Iniciar producción</figcaption></figure>\n<div class=\"mn-nota\">El turno nace al pulsar <b>Iniciar producción</b> (Diurno o Nocturno, según la hora). Mirar la pantalla no lo crea.<br>Los bolsones son las bolsas grandes donde va la papa a granel.<br>Si no hay papa recibida pero el inventario general tiene, se descuenta de ahí.</div>\n<hr>\n<h2>Cómo hago las etapas</h2>\n<ol start=\"1\">\n<li>En <b>Etapas del proceso</b>, mira la que dice <b>Ahora</b> (se hacen una a una, en orden): Recepción de insumos, Despiedre, Lavado, Rallado, Tina de almidón, Centrifugado, Freído, Centrifugadora final, Salado y Empaque.</li>\n<li>En la primera, escribe los <b>Kilos de papa que entran al turno</b>.</li>\n<li>Pulsa <b>Terminar etapa</b>.</li>\n<li>Repite con cada etapa. Cuando la etapa esté lista, pulsa <b>Terminar etapa</b> otra vez.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-04.png\" alt=\"Etapas del turno\" loading=\"lazy\"><figcaption>Etapas del turno</figcaption></figure>\n<hr>\n<h2>Cómo marco quién fríe</h2>\n<ol start=\"1\">\n<li>En la etapa <b>Freído</b>, pulsa <b>¿Quién fríe en este turno?</b>.</li>\n<li>Elige a la persona.</li>\n<li>Pulsa <b>Marcar</b>.</li>\n</ol>\n<div class=\"mn-nota\">Cada persona marcada gana el Bono Fritura de su jornada. Si te equivocas, pulsa <b>Quitar</b>.</div>\n<hr>\n<h2>Cómo anoto la merma y cierro el turno</h2>\n<ol start=\"1\">\n<li>Cuando todo pasó a Empaque, el sistema muestra <b>Merma del proceso</b> y calcula la merma.</li>\n<li>Verás una fila por etapa (Despiedre, Lavado, Rallado, Tina de almidón, Centrifugado, Freído, Centrifugadora final y Salado). En cada etapa donde se perdió papa, escribe los kilos.</li>\n<li>Toca el motivo principal: <b>Cáscara</b>, <b>Tierra</b>, <b>Aceite</b>, <b>Derrame</b> u <b>Otra</b> (con <b>Otra</b> escribe qué fue).</li>\n<li>Deja vacía la etapa sin pérdida. <b>Poner todo aquí</b> llena lo que falta del tramo.</li>\n<li>Mira el total en vivo.</li>\n<li>Si el total no cuadra, escribe por qué.</li>\n<li>Pulsa <b>Anotar merma y cerrar turno</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-06.png\" alt=\"Merma por etapas\" loading=\"lazy\"><figcaption>Merma por etapas</figcaption></figure>\n<ol start=\"8\">\n<li>Aparece <b>Cerrar el turno</b>. Pulsa <b>Sí, cerrar el turno</b> (o <b>Todavía no</b> para volver).</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-07.png\" alt=\"Confirmar el cierre del turno\" loading=\"lazy\"><figcaption>Confirmar el cierre del turno</figcaption></figure>\n<div class=\"mn-nota\">Es una sola vez por turno. La diferencia que no se explica queda como «Sin explicar».<br>Antes de cerrar la puedes corregir con <b>Corregir</b>. Ya cerrado el turno, solo Gerencia la corrige.</div>\n<hr>\n<h2>Cómo veo el resumen del turno</h2>\n<ol start=\"1\">\n<li>En <b>Producir</b>, abre la pestaña <b>Resumen</b>.</li>\n<li>Elige <b>Turno</b>, <b>Día</b>, <b>Semana</b> o <b>Mes</b>.</li>\n<li>Mira el bloque <b>Avisos</b>: lo que requiere atención.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-08.png\" alt=\"Resumen de Producción\" loading=\"lazy\"><figcaption>Resumen de Producción</figcaption></figure>\n<hr>\n<h2>Cómo veo el inventario disponible</h2>\n<ol start=\"1\">\n<li>Pulsa el botón grande <b>Inventario disponible</b>.</li>\n<li>Mira la barra de cada insumo: verde si alcanza, amarillo si se acerca al mínimo, rojo si está en el mínimo o por debajo.</li>\n<li>Entre los insumos están <b>Bolsones</b> y <b>Bolsas de presentación</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-09.png\" alt=\"Inventario disponible\" loading=\"lazy\"><figcaption>Inventario disponible</figcaption></figure>\n<div class=\"mn-nota\">Producción solo lo mira. El mínimo lo define Gerencia o Administración.</div>\n<hr>\n<h2>Cómo agrego a quien recibe</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Equipo</b>.</li>\n<li>En la tarjeta <b>Quién recibe</b>, escribe el nombre en <b>Agregar persona</b>.</li>\n<li>Pulsa <b>Agregar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-10.png\" alt=\"Equipo: Quién recibe\" loading=\"lazy\"><figcaption>Equipo: Quién recibe</figcaption></figure>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>El botón «Iniciar producción» está apagado</h3>\n<p>Es porque falta algún requisito o no hay personal marcado.</p>\n<ol start=\"1\">\n<li>Mira cuál requisito sale en rojo.</li>\n<li>Si falta un insumo o los <b>Bolsones</b> (sale «Faltan bolsones. Administración debe comprarlos y Producción recibirlos»): avisa a Administración para que compre. Cuando llegue, recíbelo en <b>Recibir</b>.</li>\n<li>Si falta personal: avisa a Recursos humanos para que arme el grupo y marque la entrada.</li>\n<li>Cuando todo esté en verde, pulsa <b>Iniciar producción</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-11.png\" alt=\"Requisito en rojo y botón apagado\" loading=\"lazy\"><figcaption>Requisito en rojo y botón apagado</figcaption></figure>\n<div class=\"mn-nota\">Ni Gerencia puede saltarse el requisito de bolsones.</div>\n<h3>La compra llegó distinta a lo pedido</h3>\n<ol start=\"1\">\n<li>En <b>Recibir</b>, escribe lo que de verdad llegó.</li>\n<li>Confirma el aviso y escribe el motivo.</li>\n</ol>\n<h3>No me cuadra la merma</h3>\n<ol start=\"1\">\n<li>Escribe en cada etapa lo que pasó.</li>\n<li>Si el total sigue sin cuadrar, escribe por qué en la nota.</li>\n<li>Pulsa <b>Anotar merma y cerrar turno</b>: la diferencia queda como «Sin explicar».</li>\n</ol>\n<h3>Necesito algo que no puedo cambiar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Autorización</b>, arriba.</li>\n<li>Pulsa <b>Pedir autorización</b>.</li>\n<li>En <b>¿Qué quieres cambiar?</b> elige lo que necesitas.</li>\n<li>Escribe el <b>Motivo (obligatorio)</b>.</li>\n<li>Pulsa <b>Enviar solicitud</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/produccion-12.png\" alt=\"Ventana para pedir autorización\" loading=\"lazy\"><figcaption>Ventana para pedir autorización</figcaption></figure>\n<h3>Quiero saber qué respondieron</h3>\n<ol start=\"1\">\n<li>Abre <b>Mis solicitudes</b>.</li>\n<li>Mira la respuesta de Gerencia.</li>\n</ol>","pasos":58,"fotos":11},"logistica":{"n":"Logística","html":"<h2>Qué hace Logística</h2>\n<p>Logística empaca la papa terminada, arma las salidas por zona, despacha con vehículo y chofer, cuenta la carga y marca las entregas. Si se pierde algo al empacar, anota la merma.</p>\n<p>Logística <b>no ve precios ni costos</b>.</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Logística</b>.</li>\n<li>En <b>Empacar</b>, mira los requisitos y anota lo empacado.</li>\n<li>En <b>Zonas</b>, mira los pedidos del día.</li>\n<li>Arma la salida y despacha.</li>\n<li>Cuenta la carga, marca <b>en ruta</b> y marca <b>entregada</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Logística</b>.</li>\n<li>Se abre <b>Zonas</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-01.png\" alt=\"Zonas del día\" loading=\"lazy\"><figcaption>Zonas del día</figcaption></figure>\n<hr>\n<h2>Cómo anoto lo empacado</h2>\n<ol start=\"1\">\n<li>Pulsa el botón grande <b>Empacar</b>.</li>\n<li>Mira <b>Papa a granel disponible</b>.</li>\n<li>Mira <b>Requisitos para empacar</b>: <b>Bolsas de presentación</b> y <b>Personal en planta</b> deben salir en verde.</li>\n<li>En <b>Anotar empaque</b>, escribe los <b>Bultos</b> de cada presentación.</li>\n<li>Si hubo pérdida, abre <b>Merma de empaque (opcional)</b> y escribe los kilos y el motivo.</li>\n<li>Pulsa <b>Anotar empaque</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-02.png\" alt=\"Empacar con requisitos\" loading=\"lazy\"><figcaption>Empacar con requisitos</figcaption></figure>\n<div class=\"mn-nota\">No hace falta un turno abierto.<br>El sistema calcula los kilos, descuenta las bolsas y suma al inventario: Ventas puede vender enseguida.<br>No te deja pasar de lo disponible.</div>\n<hr>\n<h2>Cómo miro las zonas del día</h2>\n<ol start=\"1\">\n<li>Pulsa el botón grande <b>Zonas</b>.</li>\n<li>Cada tarjeta es una zona (Aragua, Lara, Capital...) y muestra los kilos listos y los pedidos.</li>\n<li>Toca la tarjeta de una zona para abrirla.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-03.png\" alt=\"Tarjetas de zonas\" loading=\"lazy\"><figcaption>Tarjetas de zonas</figcaption></figure>\n<div class=\"mn-nota\">Es el punto de partida de Logística.</div>\n<hr>\n<h2>Cómo armo y despacho una zona</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Zonas</b> y toca la tarjeta de la zona.</li>\n<li>En <b>Pedidos por despachar</b>, marca los pedidos que salen.</li>\n<li>Pulsa <b>Armar salida con lo marcado</b>.</li>\n<li>La salida aparece en <b>Salidas armadas</b>.</li>\n<li>Si quedas por debajo de la meta o partes un pedido, escribe el motivo.</li>\n<li>Pulsa <b>Despachar</b> en la salida.</li>\n<li>Elige el vehículo y el chofer.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-04.png\" alt=\"Armar la salida\" loading=\"lazy\"><figcaption>Armar la salida</figcaption></figure>\n<div class=\"mn-nota\"><b>Pausar la zona</b> pide un motivo. Al despachar se emiten las notas de entrega o facturas.</div>\n<hr>\n<h2>Cómo cuento la carga y marco la entrega</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Despachos</b>.</li>\n<li>Abre la pestaña <b>Contar la carga de las salidas</b>.</li>\n<li>Cuenta la carga y pulsa <b>Guardar la carga</b>.</li>\n<li>Pulsa <b>Marcar en ruta</b> al salir.</li>\n<li>Pulsa <b>Marcar entregada</b> al llegar.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-05.png\" alt=\"Despachos\" loading=\"lazy\"><figcaption>Despachos</figcaption></figure>\n<div class=\"mn-nota\">En <b>Notas de entrega</b>, <b>Ver nota</b> abre la nota. Si aún no hay vehículos, Gerencia o Administración los cargan.</div>\n<hr>\n<h2>Cómo anoto una merma</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Mermas</b>.</li>\n<li>Abre la pestaña <b>Registrar merma</b>.</li>\n<li>Elige la <b>Etapa donde se perdió</b> y el <b>Lote</b>.</li>\n<li>Elige cómo cuentas: <b>En unidades (bolsas)</b> o <b>En kilos</b>.</li>\n<li>Escribe las <b>Unidades perdidas</b> y elige la <b>Causa</b>.</li>\n<li>Pulsa <b>Registrar merma</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-06.png\" alt=\"Registrar merma\" loading=\"lazy\"><figcaption>Registrar merma</figcaption></figure>\n<hr>\n<h2>Cómo veo el inventario disponible</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Existencias</b>.</li>\n<li>Abre <b>Movimientos y límites</b>.</li>\n<li>Mira la barra de cada producto: verde si alcanza, amarillo si se acerca al mínimo, rojo si está por debajo.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-09.png\" alt=\"Existencias frente al mínimo\" loading=\"lazy\"><figcaption>Existencias frente al mínimo</figcaption></figure>\n<div class=\"mn-nota\">Logística solo lo mira.</div>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>El botón «Anotar empaque» está apagado</h3>\n<ol start=\"1\">\n<li>Mira qué requisito sale en rojo.</li>\n<li>Si faltan bolsas de presentación: pide a Administración que compre.</li>\n<li>Si falta personal: pide a Recursos humanos que marque la asistencia.</li>\n<li>Cuando esté en verde, pulsa <b>Anotar empaque</b>.</li>\n</ol>\n<h3>Armé una salida equivocada</h3>\n<ol start=\"1\">\n<li>En la zona, busca la salida en <b>Salidas armadas</b>.</li>\n<li>Pulsa <b>Anular</b>.</li>\n<li>Escribe un motivo corto (al menos 3 letras).</li>\n</ol>\n<div class=\"mn-nota\">La salida queda anulada, no borrada.</div>\n<h3>Necesito algo que no puedo cambiar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Autorización</b>, arriba.</li>\n<li>Pulsa <b>Pedir autorización</b>.</li>\n<li>En <b>¿Qué quieres cambiar?</b> elige lo que necesitas.</li>\n<li>Escribe el <b>Motivo (obligatorio)</b>.</li>\n<li>Pulsa <b>Enviar solicitud</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/logistica-08.png\" alt=\"Ventana para pedir autorización\" loading=\"lazy\"><figcaption>Ventana para pedir autorización</figcaption></figure>\n<h3>Quiero saber qué respondieron</h3>\n<ol start=\"1\">\n<li>Abre <b>Mis solicitudes</b>.</li>\n<li>Mira la respuesta de Gerencia.</li>\n</ol>","pasos":52,"fotos":8},"ventas":{"n":"Ventas","html":"<h2>Qué hace Ventas</h2>\n<p>Ventas atiende a los clientes: busca al cliente, arma el pedido, lo registra y entrega la nota de entrega o la factura. También mira cuánto producto hay disponible, quién debe y cómo van las ventas.</p>\n<p>Ventas <b>no cambia precios</b>. Si un precio no está o está mal, se pide a Gerencia o Administración con «Pedir autorización».</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Ventas</b>.</li>\n<li>Mira <b>Existencias</b> para saber qué hay disponible.</li>\n<li>Haz cada venta en <b>Hacer una venta</b>.</li>\n<li>Mira <b>Quién debe</b> y recuérdale el pago a quien debe.</li>\n<li>Al terminar, mira <b>Reportes de ventas</b> para ver cómo va el día.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Ventas</b>.</li>\n<li>Se abre la pantalla <b>Vender</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-01.png\" alt=\"Pantalla para elegir el puesto\" loading=\"lazy\"><figcaption>Pantalla para elegir el puesto</figcaption></figure>\n<div class=\"mn-nota\">Si ves otro puesto arriba, pulsa <b>Cambiar rol</b> (a la izquierda) y elige <b>Ventas</b>.</div>\n<hr>\n<h2>Cómo hago una venta</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Vender</b>. Se abre <b>Hacer una venta</b>.</li>\n<li>En <b>Buscar cliente por nombre o RIF</b> escribe el nombre del cliente.</li>\n<li>Toca al cliente en la lista.</li>\n<li>En <b>Catálogo</b>, busca el producto (puedes tocar <b>Papas</b> o <b>Salsas</b>).</li>\n<li>Pon los bultos del producto con <b>+</b> y <b>−</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-02.png\" alt=\"Cliente elegido y bultos en el pedido\" loading=\"lazy\"><figcaption>Cliente elegido y bultos en el pedido</figcaption></figure>\n<ol start=\"6\">\n<li>Mira el <b>Total</b> en <b>Pedido y facturación</b>.</li>\n<li>En <b>¿Cómo paga?</b> deja marcado <b>A crédito</b>: la cuenta queda por cobrar y el pago lo registra Administración.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-03.png\" alt=\"Forma de pago del pedido\" loading=\"lazy\"><figcaption>Forma de pago del pedido</figcaption></figure>\n<ol start=\"8\">\n<li>Pulsa <b>REGISTRAR PEDIDO · NOTA DE ENTREGA</b> (o <b>REGISTRAR PEDIDO · FACTURA</b> si el cliente pide factura).</li>\n<li>Pulsa <b>Descargar PDF</b> y entrégale el documento al cliente.</li>\n</ol>\n<div class=\"mn-nota\">Si no está el cliente: mira «Cómo agrego un cliente nuevo».</div>\n<hr>\n<h2>Cómo veo qué hay disponible</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Vender</b>.</li>\n<li>Pulsa el botón <b>Existencias</b>.</li>\n<li>Busca el producto: ves cuántos bultos hay.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-04.png\" alt=\"Existencias disponibles\" loading=\"lazy\"><figcaption>Existencias disponibles</figcaption></figure>\n<div class=\"mn-nota\">También en el <b>Catálogo</b> de cada venta aparece «Disponibles: N bultos» debajo de cada producto.</div>\n<hr>\n<h2>Cómo agrego un cliente nuevo</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Clientes</b>.</li>\n<li>Pulsa <b>Cliente nuevo</b>.</li>\n<li>Escribe la razón social o el nombre.</li>\n<li>Escribe el RIF o la identificación.</li>\n<li>Elige el <b>estado</b> del cliente (es obligatorio: de ahí sale la zona de entrega).</li>\n<li>Elige su categoría de precio: <b>Minorista</b>, <b>Mayorista</b> o <b>Gran Mayor</b>.</li>\n<li>Escribe la dirección de entrega, el vendedor, la modalidad habitual y el teléfono.</li>\n<li>Pulsa <b>Guardar</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-05.png\" alt=\"Formulario de cliente nuevo\" loading=\"lazy\"><figcaption>Formulario de cliente nuevo</figcaption></figure>\n<div class=\"mn-nota\">También puedes pulsar <b>Cliente nuevo</b> dentro de <b>Hacer una venta</b>.</div>\n<hr>\n<h2>Cómo veo quién debe</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Cuentas</b>.</li>\n<li>Abre <b>Quién debe</b>.</li>\n<li>Busca al cliente en la lista.</li>\n<li>Pulsa <b>WhatsApp</b> o <b>Llamar</b> para recordarle el pago.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-06.png\" alt=\"Lista de quién debe\" loading=\"lazy\"><figcaption>Lista de quién debe</figcaption></figure>\n<hr>\n<h2>Cómo veo los cobros hechos</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b> y elige <b>Cuentas</b>.</li>\n<li>Abre <b>Cobros hechos</b>.</li>\n<li>Mira la tabla de cobros.</li>\n<li>Si la necesitas, pulsa <b>Descargar CSV</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-07.png\" alt=\"Cobros hechos\" loading=\"lazy\"><figcaption>Cobros hechos</figcaption></figure>\n<hr>\n<h2>Cómo veo los reportes de ventas</h2>\n<ol start=\"1\">\n<li>Pulsa <b>Opciones</b>, elige <b>Cuentas</b> y abre <b>Registro de ventas</b>.</li>\n<li>Busca la tarjeta <b>Reportes de ventas</b>. En <b>Soy el vendedor</b> elige tu nombre.</li>\n<li>Elige la pestaña: <b>Por rubro</b>, <b>Por vendedor</b>, <b>Por zona</b> o <b>Por producto</b>.</li>\n<li>Elige el período: <b>Hoy</b>, <b>Esta semana</b>, <b>Quincena</b>, <b>Este mes</b> o <b>Mes pasado</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-08.png\" alt=\"Reportes de ventas\" loading=\"lazy\"><figcaption>Reportes de ventas</figcaption></figure>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>El sistema no me deja registrar la venta</h3>\n<p>Pasa si: no hay existencias, falta el precio o el cliente pasó su límite de crédito («El pedido supera el crédito disponible»).</p>\n<ol start=\"1\">\n<li>Lee el aviso rojo que sale junto al cliente y junto a los botones.</li>\n<li>Baja las cantidades o cambia de producto o de cliente.</li>\n<li>Si hace falta más crédito, pídelo a Gerencia con «Pedir autorización».</li>\n<li>Pulsa otra vez el botón de registrar.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-09.png\" alt=\"Aviso junto al botón de registrar\" loading=\"lazy\"><figcaption>Aviso junto al botón de registrar</figcaption></figure>\n<h3>Falta un precio</h3>\n<ol start=\"1\">\n<li>Avisa a Gerencia o Administración.</li>\n<li>O pulsa <b>Autorización</b> (arriba) y luego <b>Pedir autorización</b>.</li>\n</ol>\n<h3>Necesito algo que no puedo cambiar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Autorización</b>, arriba.</li>\n<li>Pulsa <b>Pedir autorización</b>.</li>\n<li>En <b>¿Qué quieres cambiar?</b> elige lo que necesitas.</li>\n<li>Escribe el <b>Motivo (obligatorio)</b>.</li>\n<li>Pulsa <b>Enviar solicitud</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/ventas-10.png\" alt=\"Ventana para pedir autorización\" loading=\"lazy\"><figcaption>Ventana para pedir autorización</figcaption></figure>\n<h3>Quiero saber qué respondieron</h3>\n<ol start=\"1\">\n<li>Abre <b>Mis solicitudes</b>.</li>\n<li>Mira la respuesta de Gerencia.</li>\n</ol>","pasos":53,"fotos":10},"recursos-humanos":{"n":"Recursos humanos","html":"<h2>Qué hace Recursos humanos</h2>\n<p>Recursos humanos cuida a las personas de la empresa: marca quién entra y quién sale, arma los grupos de turno, agrega al personal, importa las marcas del lector de huellas, revisa la asistencia y paga la nómina.</p>\n<p>Recursos humanos <b>no cambia</b> las reglas de pago ni los bonos: eso es de Gerencia. Sí puede cambiar los horarios de los turnos.</p>\n<h2>Mi día en 5 pasos</h2>\n<ol start=\"1\">\n<li>Entra al sistema y elige <b>Recursos humanos</b>.</li>\n<li>En <b>En planta hoy</b>, marca la entrada de cada persona (o de todo el grupo).</li>\n<li>Al final del turno, marca la salida.</li>\n<li>Mira <b>Asistencia</b> y <b>Bonos</b> para ver que todo cuadre.</li>\n<li>En fechas de pago, entra en <b>Pagar nómina</b>.</li>\n</ol>\n<hr>\n<h2>Cómo entro y elijo mi puesto</h2>\n<ol start=\"1\">\n<li>Abre el sistema.</li>\n<li>Pulsa el botón <b>Recursos humanos</b>.</li>\n<li>Se abre <b>En planta hoy</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-01.png\" alt=\"Pantalla de inicio de Recursos humanos\" loading=\"lazy\"><figcaption>Pantalla de inicio de Recursos humanos</figcaption></figure>\n<hr>\n<h2>Cómo marco la entrada y la salida</h2>\n<ol start=\"1\">\n<li>Entra en <b>En planta hoy</b>.</li>\n<li>En <b>Marcar entrada y salida</b>, busca a la persona.</li>\n<li>Pulsa <b>Marcar entrada</b> cuando llega.</li>\n<li>Pulsa <b>Marcar salida</b> cuando se va.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-02.png\" alt=\"Marcar entrada y salida de una persona\" loading=\"lazy\"><figcaption>Marcar entrada y salida de una persona</figcaption></figure>\n<div class=\"mn-nota\">Si el botón está apagado y dice «Falta el turno en Personal», mira «Si algo sale mal».</div>\n<h3>Para marcar a todo el grupo de una vez</h3>\n<ol start=\"1\">\n<li>En el turno (Diurno o Nocturno) pulsa <b>Marcar entrada a todo el grupo</b>.</li>\n<li>Si alguien faltó, pulsa <b>Quitar entrada</b> en su fila.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-03.png\" alt=\"Marcar entrada a todo el grupo\" loading=\"lazy\"><figcaption>Marcar entrada a todo el grupo</figcaption></figure>\n<hr>\n<h2>Cómo armo los grupos de turno</h2>\n<ol start=\"1\">\n<li>Entra en <b>Grupos de turno</b>.</li>\n<li>Elige quién integra el <b>Grupo 1</b>.</li>\n<li>Elige quién integra el <b>Grupo 2</b>.</li>\n<li>Elige qué turno tiene cada grupo esta semana (<b>Diurno</b> o <b>Nocturno</b>).</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-04.png\" alt=\"Grupos de turno\" loading=\"lazy\"><figcaption>Grupos de turno</figcaption></figure>\n<div class=\"mn-nota\">Los turnos y los grupos son solo de planta (Producción y Logística). No incluyen a Administración, Ventas ni choferes.<br>Producción solo puede iniciar si el grupo del turno tiene personal con entrada marcada.</div>\n<hr>\n<h2>Cómo agrego a una persona</h2>\n<ol start=\"1\">\n<li>Entra en <b>Personas</b>.</li>\n<li>En la tarjeta <b>Agregar persona</b>, escribe nombre y apellido.</li>\n<li>Escribe la cédula.</li>\n<li>Escribe el cargo.</li>\n<li>Elige el puesto (Gerencia, Administración, Ventas, Recursos humanos, Producción o Logística) y su área.</li>\n<li>Escribe la fecha de ingreso y el teléfono.</li>\n<li>En <b>Se le paga por</b>, elige <b>Día</b> u <b>Hora</b>, y escribe la tarifa en $.</li>\n<li>Si es de planta, elige el <b>Turno de trabajo</b> (<b>Diurno</b> o <b>Nocturno</b>).</li>\n<li>Pulsa <b>Agregar persona</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-05.png\" alt=\"Agregar persona\" loading=\"lazy\"><figcaption>Agregar persona</figcaption></figure>\n<div class=\"mn-nota\">Sin turno no se puede marcar la entrada. Si la persona maneja un vehículo, activa <b>Es chofer</b>.<br>Si al abrir <b>En planta hoy</b> o <b>Personas</b> aparece <b>Revisa estas personas</b>, indica si son de Ventas o su área de Producción.</div>\n<hr>\n<h2>Cómo cambio los horarios de los turnos</h2>\n<ol start=\"1\">\n<li>Entra en <b>Parámetros</b>.</li>\n<li>En <b>Horario por turno</b>, elige cuándo entran y salen el <b>Diurno</b> y el <b>Nocturno</b>.</li>\n<li>Elige desde qué día vale el cambio.</li>\n<li>Guarda el cambio.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-06.png\" alt=\"Horario por turno\" loading=\"lazy\"><figcaption>Horario por turno</figcaption></figure>\n<div class=\"mn-nota\">Los días que ya pasaron no cambian. No se puede empezar en días ya pagados o con bono aplicado.<br>Cada cambio queda en Auditoría y le llega un aviso a Gerencia.<br>Las reglas de pago y el bono los cambia solo Gerencia.</div>\n<hr>\n<h2>Cómo importo las marcas del lector de huellas</h2>\n<ol start=\"1\">\n<li>Entra en <b>Importar del lector</b>.</li>\n<li>Sube el archivo del lector (Hikvision).</li>\n<li>Revisa lo que el sistema entendió.</li>\n<li>Asocia los códigos nuevos a su persona.</li>\n<li>Resuelve lo dudoso.</li>\n<li>Guarda.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-07.png\" alt=\"Importar del lector\" loading=\"lazy\"><figcaption>Importar del lector</figcaption></figure>\n<div class=\"mn-nota\">La asistencia se llena sola con esas marcas.</div>\n<hr>\n<h2>Cómo reviso la asistencia</h2>\n<ol start=\"1\">\n<li>Entra en <b>Asistencia</b>.</li>\n<li>Cambia de quincena con <b>Anterior</b>, <b>Siguiente</b> y <b>Esta quincena</b>.</li>\n<li>Mira quién vino y quién faltó.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-08.png\" alt=\"Asistencia de la quincena\" loading=\"lazy\"><figcaption>Asistencia de la quincena</figcaption></figure>\n<hr>\n<h2>Cómo veo los bonos y los turnos</h2>\n<ol start=\"1\">\n<li>Entra en <b>Bonos</b>.</li>\n<li>En <b>Turno en vivo</b>, mira cuánto llevan y si califican.</li>\n<li>Entra en <b>Turnos</b>.</li>\n<li>Elige el día y el turno (<b>Diurno</b> o <b>Nocturno</b>).</li>\n<li>Mira <b>Quiénes estuvieron</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-09.png\" alt=\"Turno en vivo y bonos\" loading=\"lazy\"><figcaption>Turno en vivo y bonos</figcaption></figure>\n<div class=\"mn-nota\">Los bonos se aplican solos al cerrar el turno de Producción. Si algo no cuadra, avisa a Gerencia o a Administración (ellos pueden pulsar <b>Deshacer</b>).</div>\n<hr>\n<h2>Cómo pago la nómina</h2>\n<ol start=\"1\">\n<li>Entra en <b>Pagar nómina</b>.</li>\n<li>Elige <b>Semana</b>, <b>Quincena</b> o <b>Mes</b>.</li>\n<li>Muévete con <b>Anterior</b>, <b>Siguiente</b> y <b>Hoy</b>.</li>\n<li>Revisa la tabla: lo trabajado, horas extra, bonos, préstamo y total a pagar.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-10.png\" alt=\"Tabla de pagar nómina\" loading=\"lazy\"><figcaption>Tabla de pagar nómina</figcaption></figure>\n<ol start=\"5\">\n<li>En la fila de la persona, pulsa <b>Registrar pago</b>.</li>\n<li>Revisa base, extra, bonos y deducciones de ley.</li>\n<li>Si tiene préstamo, marca <b>Descontar la cuota del préstamo</b> y escribe el <b>Monto a descontar ($)</b>.</li>\n<li>Elige la fecha y la forma de pago (<b>Efectivo</b>, <b>Transferencia</b> o <b>Pago móvil</b>).</li>\n<li>Pulsa <b>Confirmar pago</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-11.png\" alt=\"Registrar el pago de una persona\" loading=\"lazy\"><figcaption>Registrar el pago de una persona</figcaption></figure>\n<ol start=\"10\">\n<li>Cuando la fila diga <b>Pagado</b>, pulsa <b>Recibo</b> para imprimirlo o guardarlo en PDF.</li>\n</ol>\n<div class=\"mn-nota\">La nómina se calcula en dólares. Al pagar, el sistema muestra los bolívares a la tasa BCV del día de pago.</div>\n<hr>\n<h2>Si algo sale mal</h2>\n<h3>El botón «Marcar entrada» está apagado</h3>\n<ol start=\"1\">\n<li>Mira el aviso en la fila: «Falta el turno en Personal».</li>\n<li>Entra en <b>Personas</b>.</li>\n<li>Abre a esa persona y elige su <b>Turno de trabajo</b>.</li>\n<li>Vuelve a <b>En planta hoy</b> y marca la entrada.</li>\n</ol>\n<h3>Marqué la entrada a alguien que faltó</h3>\n<ol start=\"1\">\n<li>En <b>En planta hoy</b>, busca a la persona.</li>\n<li>Pulsa <b>Quitar entrada</b>.</li>\n</ol>\n<h3>Producción no puede iniciar el turno</h3>\n<ol start=\"1\">\n<li>Revisa en <b>Grupos de turno</b> que el grupo del turno tenga personal.</li>\n<li>Revisa en <b>En planta hoy</b> que esa gente tenga la entrada marcada.</li>\n</ol>\n<h3>Necesito algo que no puedo cambiar</h3>\n<ol start=\"1\">\n<li>Pulsa <b>Autorización</b>, arriba.</li>\n<li>Pulsa <b>Pedir autorización</b>.</li>\n<li>En <b>¿Qué quieres cambiar?</b> elige lo que necesitas.</li>\n<li>Escribe el <b>Motivo (obligatorio)</b>.</li>\n<li>Pulsa <b>Enviar solicitud</b>.</li>\n</ol>\n<figure><img src=\"/manuales/img/recursos-humanos-12.png\" alt=\"Ventana para pedir autorización\" loading=\"lazy\"><figcaption>Ventana para pedir autorización</figcaption></figure>\n<h3>Quiero saber qué respondieron</h3>\n<ol start=\"1\">\n<li>Abre <b>Mis solicitudes</b>.</li>\n<li>Mira la respuesta de Gerencia.</li>\n</ol>","pasos":70,"fotos":12}};
